"""Disposable deterministic patch generator for WO88F activation."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one replacement, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8", newline="\n")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")


marker = "    def register_physical_capacity_policy(\n"
method = '''    def activate_world_from_initial_manifest(\n        self, world_id: Any, manifest_key: Any, version: Any, activated_by: Any\n    ) -> dict[str, Any]:\n        """Active H/phi/P atomiquement depuis un manifeste T0 scellé.\n\n        Cette opération de cutover ne reconstruit aucune histoire, n'émet aucun\n        événement canonique et ne touche jamais ``need_state``. Elle exige un\n        runtime proprement arrêté au T0, un système ``prepared`` sur le modèle\n        sélectionné, une couverture dense du manifeste, une politique P valide\n        et une politique de terminaison du sommeil assignée.\n        """\n        world = self._world_id(world_id)\n        self._require_world(world)\n        key = _key(manifest_key, field="manifeste")\n        ver = _version(version)\n        actor = _key(activated_by, field="acteur d'activation")\n        now = self._now()\n\n        with transaction(self._conn) as conn:\n            system = conn.execute(\n                "SELECT status,prepared_model_key,prepared_model_version FROM world_physiology_system "\n                "WHERE world_id=?", (world,),\n            ).fetchone()\n            if system is None or system["status"] != "prepared":\n                raise SleepPhysiologyError(\n                    "système physiologique non préparé", code="physiology_not_prepared"\n                )\n            if system["prepared_model_key"] != ADDITIVE_MODEL_KEY \\\n                    or int(system["prepared_model_version"] or 0) != 1:\n                raise SleepPhysiologyError("modèle préparé incompatible", code="invalid_model")\n            if conn.execute(\n                "SELECT 1 FROM runtime_session WHERE world_id=? AND stopped_at IS NULL",\n                (world,),\n            ).fetchone() is not None:\n                raise SleepPhysiologyError("session runtime ouverte", code="runtime_session_open")\n\n            manifest = self.initial_physiology_manifest(world, key, ver)\n            if manifest["sealed_at"] is None:\n                raise SleepPhysiologyError(\n                    "manifeste initial non scellé", code="manifest_not_sealed"\n                )\n            if manifest["model_key"] != ADDITIVE_MODEL_KEY or int(manifest["model_version"]) != 1:\n                raise SleepPhysiologyError("modèle du manifeste incompatible", code="invalid_model")\n            frozen = self._frozen_manifest_t0(world)\n            if _at(manifest["anchor_at"]) != frozen:\n                raise SleepPhysiologyError(\n                    "manifeste hors T0 canonique gelé", code="canonical_t0_mismatch"\n                )\n\n            # Revalider sous la même transaction ferme le TOCTOU entre preuve et cutover.\n            characters = self.validate_initial_physiology_manifest(world, key, ver)\n            self.validate_physical_capacity_configuration(world)\n            if conn.execute(\n                "SELECT 1 FROM world_sleep_termination_policy_assignment WHERE world_id=?",\n                (world,),\n            ).fetchone() is None:\n                raise SleepPhysiologyError(\n                    "politique de terminaison du sommeil absente",\n                    code="sleep_termination_policy_missing",\n                )\n\n            for table in (\n                "sleep_regulation_state", "physical_capacity_state",\n                "sleep_wake_hysteresis_state", "sleep_regulation_precision_state",\n            ):\n                if conn.execute(\n                    f"SELECT 1 FROM {table} WHERE world_id=? LIMIT 1", (world,)\n                ).fetchone() is not None:\n                    raise SleepPhysiologyError(\n                        "état physiologique préexistant", code="activation_state_exists"\n                    )\n\n            entries = conn.execute(\n                "SELECT e.character_id,e.homeostatic_load_milli,e.circadian_phase_milli,"\n                "e.physical_capacity_milli,e.previous_band,e.homeostatic_load_residue,"\n                "e.circadian_phase_residue,e.physical_capacity_remainder "\n                "FROM initial_physiology_manifest_entry e WHERE e.manifest_id=? "\n                "ORDER BY e.character_id", (manifest["manifest_id"],),\n            ).fetchall()\n            if len(entries) != len(characters):\n                raise SleepPhysiologyError(\n                    "couverture de manifeste incomplète", code="incomplete_initial_manifest"\n                )\n\n            for entry in entries:\n                character_id = int(entry["character_id"])\n                conn.execute(\n                    "INSERT INTO sleep_regulation_state "\n                    "(public_id,world_id,character_id,model_key,model_version,"\n                    "homeostatic_load_milli,circadian_phase_milli,anchor_at,updated_at) "\n                    "VALUES (?,?,?,?,1,?,?,?,?)",\n                    (new_uuid(), world, character_id, ADDITIVE_MODEL_KEY,\n                     int(entry["homeostatic_load_milli"]), int(entry["circadian_phase_milli"]),\n                     frozen, now),\n                )\n                conn.execute(\n                    "INSERT INTO physical_capacity_state "\n                    "(public_id,world_id,character_id,capacity_milli,rate_remainder,anchor_at,updated_at) "\n                    "VALUES (?,?,?,?,?,?,?)",\n                    (new_uuid(), world, character_id, int(entry["physical_capacity_milli"]),\n                     int(entry["physical_capacity_remainder"]), frozen, now),\n                )\n                conn.execute(\n                    "INSERT INTO sleep_wake_hysteresis_state "\n                    "(public_id,world_id,character_id,previous_band,anchor_at,updated_at) "\n                    "VALUES (?,?,?,?,?,?)",\n                    (new_uuid(), world, character_id, entry["previous_band"], frozen, now),\n                )\n                conn.execute(\n                    "INSERT INTO sleep_regulation_precision_state "\n                    "(public_id,world_id,character_id,homeostatic_load_residue,"\n                    "circadian_phase_residue,anchor_at,updated_at) VALUES (?,?,?,?,?,?,?)",\n                    (new_uuid(), world, character_id, float(entry["homeostatic_load_residue"]),\n                     float(entry["circadian_phase_residue"]), frozen, now),\n                )\n\n            changed = conn.execute(\n                "UPDATE world_physiology_system SET status='active',activated_at=?,"\n                "activated_by=?,updated_at=? WHERE world_id=? AND status='prepared'",\n                (now, actor, now, world),\n            )\n            if changed.rowcount != 1:\n                raise SleepPhysiologyError(\n                    "gate physiologique modifié pendant activation", code="activation_race"\n                )\n\n        return {\n            "world_id": world, "status": "active", "model_key": ADDITIVE_MODEL_KEY,\n            "model_version": 1, "anchor_at": frozen, "manifest_key": key,\n            "manifest_version": ver, "character_count": len(characters),\n            "activated_at": now, "activated_by": actor,\n        }\n\n'''
replace_once("src/vivarium/sleep_physiology.py", marker, method + marker)

write(
    "tests/test_physiology_activation.py",
    '''"""WO88F : cutover atomique depuis le manifeste T0 scellé."""\nfrom dataclasses import asdict,replace\nfrom datetime import datetime,timezone\n\nimport pytest\n\nfrom vivarium.circadian_model import calibration_profiles\nfrom vivarium.db import connect_database\nfrom vivarium.integration_world import IntegrationWorldService\nfrom vivarium.migrations import ensure_schema\nfrom vivarium.runtime_session import RuntimeSessionService\nfrom vivarium.sleep_physiology import (ADDITIVE_MODEL_KEY,InitialPhysiologyManifestEntry,SleepPhysiologyError,SleepPhysiologyFoundationService,SleepPhysiologyService,V1_PHYSICAL_LOAD_CLASS_BY_ACTIVITY)\nfrom vivarium.sleep_termination import SleepTerminationFoundationService\nfrom vivarium.util import to_iso\n\nT0_DT=datetime(2026,8,12,21,0,tzinfo=timezone.utc);T0=to_iso(T0_DT)\nclass FixedClock:\n def now(self):return T0_DT\n def now_iso(self):return T0\n\ndef profile():\n p=asdict(calibration_profiles()["human_reference_candidate.v1"]);[p.pop(k) for k in ("profile_key","version","evidence_class")];return {"model_key":ADDITIVE_MODEL_KEY,"parameters":p}\n\ndef configured_world(*,seal=True,prepare=True):\n conn=connect_database(":memory:");ensure_schema(conn);clock=FixedClock();wid=IntegrationWorldService(conn,clock=clock).create_initial_world()["id"];sessions=RuntimeSessionService(conn,clock=clock);sessions.stop(sessions.start(wid).session_id);f=SleepPhysiologyFoundationService(conn,clock=clock)\n f.register_light_schedule("activation.day.v1",1,{"schema_version":1,"segments":[{"start_second":0,"end_second":86400,"environmental_light_milli":90000}]});f.register_location_light_profile("activation.indoor.v1",1,25000,{"kind":"indoor"});f.register_biology_profile("activation.human.v1",1,"human_reference",profile())\n f.register_initial_physiology_policy("activation.t0.v1",1,{"schema_version":1,"model_key":ADDITIVE_MODEL_KEY,"model_version":1,"homeostatic_load_region":{"min_milli":40000,"max_milli":60000},"physical_capacity_region":{"min_milli":70000,"max_milli":90000},"bootstrap_rule":"wake_stability.stable_seed.v1","residue_rule":"zero_at_t0.v1"},"test");f.register_t0_phase_rule("activation.phase.v1",1,{"schema_version":1,"rule_kind":"schedule_light_phase_windows.v1","light_phase_windows":[[200000,300000]],"dark_phase_windows":[[700000,800000]]},"test")\n f.register_physical_capacity_policy("activation.p.v1",1,{"schema_version":1,"activity_cost_per_hour_milli":{"none":3600,"light":7200,"moderate":10800,"vigorous":18000},"minimum_capacity_milli":{"none":0,"light":10000,"moderate":25000,"vigorous":45000},"traversal_cost_per_edge_milli":250,"recovery_per_hour_milli":{"rest":7200,"sleep":10800}},"test")\n f.assign_light_schedule(wid,"activation.day.v1",1,T0,"test")\n for row in conn.execute("SELECT key FROM location WHERE world_id=?",(wid,)):f.assign_location_light_profile(wid,row["key"],"activation.indoor.v1",1,T0,"test")\n for row in conn.execute("SELECT key FROM character WHERE world_id=?",(wid,)):f.assign_biology_profile(wid,row["key"],"activation.human.v1",1,"test")\n f.assign_physical_capacity_policy(wid,"activation.p.v1",1,"test")\n for typ,load in V1_PHYSICAL_LOAD_CLASS_BY_ACTIVITY.items():conn.execute("UPDATE activity_definition SET physical_load_class=? WHERE world_id=? AND activity_type=?",(load,wid,typ))\n term=SleepTerminationFoundationService(conn,clock=clock);term.register_policy("activation.sleep.v1",1,{"schema_version":1,"checkpoint_interval_seconds":900,"hard_cap_seconds":28800,"wake_admissible_enter_milli":65000,"wake_admissible_exit_milli":55000},"test");term.assign_policy(wid,"activation.sleep.v1",1,"test")\n f.create_initial_physiology_manifest(wid,"rodage.t0.v1",1,"activation.t0.v1",1,"activation.phase.v1",1,T0,"test","T0 explicite")\n for key in (row["key"] for row in conn.execute("SELECT key FROM character WHERE world_id=? ORDER BY key",(wid,))):f.append_initial_physiology_manifest_entry(wid,"rodage.t0.v1",1,InitialPhysiologyManifestEntry(key,"activation.human.v1",1,50000,250000,75000,"fragile","test","T0 explicite"))\n if seal:f.seal_initial_physiology_manifest(wid,"rodage.t0.v1",1)\n if prepare:f.prepare_world(wid,ADDITIVE_MODEL_KEY,1,"test")\n return conn,wid,clock,f\n\ndef legacy(conn,wid):return tuple(tuple(r) for r in conn.execute("SELECT character_id,need_key,value_milli,rate_remainder,anchor_at FROM need_state WHERE world_id=? ORDER BY character_id,need_key",(wid,)))\n\ndef test_activation_materializes_dense_owner_state_atomically_without_canonical_history():\n conn,wid,clock,f=configured_world()\n try:\n  before_legacy=legacy(conn,wid);before_events=conn.execute("SELECT COUNT(*) FROM canonical_event WHERE world_id=?",(wid,)).fetchone()[0]\n  result=f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"rodage_operator")\n  assert result["status"]=="active" and result["anchor_at"]==T0 and result["character_count"]==4\n  assert f.system_status(wid)=="active"\n  assert legacy(conn,wid)==before_legacy\n  assert conn.execute("SELECT COUNT(*) FROM canonical_event WHERE world_id=?",(wid,)).fetchone()[0]==before_events\n  for table in ("sleep_regulation_state","physical_capacity_state","sleep_wake_hysteresis_state","sleep_regulation_precision_state"):\n   assert conn.execute(f"SELECT COUNT(*) FROM {table} WHERE world_id=?",(wid,)).fetchone()[0]==4\n  for key in ("chuu","erika","luna","sophie"):\n   state=SleepPhysiologyService(conn,clock=clock).read_state(wid,key);assert state.anchor_at==T0;assert state.regulation.homeostatic_load_milli==50000;assert state.regulation.physical_capacity_milli==75000\n finally:conn.close()\n\ndef test_activation_refuses_unsealed_manifest_without_partial_state():\n conn,wid,clock,f=configured_world(seal=False)\n try:\n  with pytest.raises(SleepPhysiologyError) as caught:f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"test")\n  assert caught.value.code=="manifest_not_sealed";assert f.system_status(wid)=="prepared";assert conn.execute("SELECT COUNT(*) FROM sleep_regulation_state WHERE world_id=?",(wid,)).fetchone()[0]==0\n finally:conn.close()\n\ndef test_activation_refuses_open_runtime_and_rolls_back_preexisting_state():\n conn,wid,clock,f=configured_world()\n try:\n  session=RuntimeSessionService(conn,clock=clock).start(wid)\n  try:\n   with pytest.raises(SleepPhysiologyError) as caught:f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"test")\n   assert caught.value.code=="runtime_session_open";assert f.system_status(wid)=="prepared"\n  finally:RuntimeSessionService(conn,clock=clock).stop(session.session_id)\n  cid=conn.execute("SELECT id FROM character WHERE world_id=? ORDER BY id LIMIT 1",(wid,)).fetchone()[0]\n  conn.execute("INSERT INTO physical_capacity_state (public_id,world_id,character_id,capacity_milli,rate_remainder,anchor_at,updated_at) VALUES ('preexisting',?,?,75000,0,?,?)",(wid,cid,T0,T0))\n  with pytest.raises(SleepPhysiologyError) as caught:f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"test")\n  assert caught.value.code=="activation_state_exists";assert f.system_status(wid)=="prepared";assert conn.execute("SELECT COUNT(*) FROM sleep_regulation_state WHERE world_id=?",(wid,)).fetchone()[0]==0\n finally:conn.close()\n\ndef test_activation_is_single_use_and_requires_prepared_gate():\n conn,wid,clock,f=configured_world()\n try:\n  f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"test")\n  with pytest.raises(SleepPhysiologyError) as caught:f.activate_world_from_initial_manifest(wid,"rodage.t0.v1",1,"test")\n  assert caught.value.code=="physiology_not_prepared"\n finally:conn.close()\n''',
)
